import React from 'react';
import styled from 'styled-components';
import Banner, { BannerItem } from '../components/common/Banner';
import { devices } from '../styles/breakpoints';

const PageWrapper = styled.div`
  width: 100%;
  padding-top: 60px;

  ${devices.tablet} {
    padding-top: 80px;
  }
`;

const ProductsWrapper = styled.div`
  padding-top: 0;
`;

const MainContent = styled.div`
  max-width: 1200px;
  margin: 0 auto;
  padding: 40px 20px;

  ${devices.tablet} {
    padding: 80px 20px;
  }
`;

const HeroSection = styled.section`
  display: flex;
  flex-direction: column;
  gap: 40px;
  margin-bottom: 60px;

  ${devices.tablet} {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
    gap: 60px;
    margin-bottom: 100px;
  }

  .text-content {
    flex: 1;
    text-align: center;

    ${devices.tablet} {
      text-align: left;
    }

    h1 {
      font-size: 28px;
      
      ${devices.tablet} {
        font-size: 36px;
      }
      color: #333;
      margin-bottom: 20px;
    }

    p {
      font-size: 14px;
      
      ${devices.tablet} {
        font-size: 16px;
      }
      color: #666;
      line-height: 1.6;
      margin-bottom: 30px;
    }

    button {
      background: #8B5CF6;
      color: white;
      border: none;
      padding: 10px 25px;
      
      ${devices.tablet} {
        padding: 12px 30px;
      }
      border-radius: 25px;
      font-size: 14px;
      
      ${devices.tablet} {
        font-size: 16px;
      }
      cursor: pointer;
      transition: background 0.3s;

      &:hover {
        background: #7C3AED;
      }
    }
  }

  .image-content {
    flex: 1;
    height: 300px;
    
    ${devices.tablet} {
      height: 400px;
    }
    background: #F8F8F8;
    border-radius: 12px;
  }
`;

const ProductSection = styled.section`
  margin-bottom: 60px;

  ${devices.tablet} {
    margin-bottom: 80px;
  }

  h2 {
    font-size: 20px;
    
    ${devices.tablet} {
      font-size: 24px;
    }
    color: #333;
    margin-bottom: 30px;

    ${devices.tablet} {
      margin-bottom: 40px;
    }
  }
`;

const ProductGrid = styled.div`
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
  margin-bottom: 30px;

  ${devices.tablet} {
    grid-template-columns: repeat(2, 1fr);
    gap: 30px;
    margin-bottom: 40px;
  }

  ${devices.laptop} {
    grid-template-columns: repeat(3, 1fr);
  }
`;

const ProductCard = styled.div`
  background: #F8F8F8;
  border-radius: 12px;
  padding: 20px;
  text-align: center;

  ${devices.tablet} {
    padding: 30px;
  }

  .product-image {
    width: 200px;
    height: 200px;

    ${devices.tablet} {
      width: 240px;
      height: 240px;
    }
    background: #E5E5E5;
    margin: 0 auto 20px;
    border-radius: 8px;
  }

  .product-dots {
    display: flex;
    justify-content: center;
    gap: 4px;
    margin-bottom: 20px;

    span {
      width: 4px;
      height: 4px;
      background: #999;
      border-radius: 50%;
    }
  }

  h3 {
    font-size: 14px;
    
    ${devices.tablet} {
      font-size: 16px;
    }
    color: #333;
    margin-bottom: 10px;
  }

  p {
    font-size: 12px;
    
    ${devices.tablet} {
      font-size: 14px;
    }
    color: #666;
    margin-bottom: 20px;
  }

  button {
    background: #8B5CF6;
    color: white;
    border: none;
    border-radius: 20px;
    padding: 8px 20px;
    
    ${devices.tablet} {
      padding: 8px 24px;
    }
    font-size: 14px;
    cursor: pointer;
    transition: background 0.3s;

    &:hover {
      background: #7C3AED;
    }
  }
`;

const ComparisonSection = styled.section`
  margin-bottom: 60px;
  overflow-x: auto;

  ${devices.tablet} {
    margin-bottom: 80px;
  }

  h2 {
    font-size: 20px;
    
    ${devices.tablet} {
      font-size: 24px;
    }
    color: #333;
    margin-bottom: 30px;

    ${devices.tablet} {
      margin-bottom: 40px;
    }
  }

  .comparison-table {
    width: 100%;
    min-width: 800px;
    border-collapse: collapse;
    background: white;
    border-radius: 12px;
    overflow: hidden;

    th, td {
      padding: 12px 15px;
      
      ${devices.tablet} {
        padding: 15px 20px;
      }
      text-align: center;
      border-bottom: 1px solid #eee;
    }

    th {
      background: #F8F8F8;
      font-weight: 500;
      color: #333;
      font-size: 12px;
      
      ${devices.tablet} {
        font-size: 14px;
      }
    }

    td {
      color: #666;
      font-size: 12px;
      
      ${devices.tablet} {
        font-size: 14px;
      }

      &:first-child {
        text-align: left;
        font-weight: 500;
        color: #333;
      }
    }

    tr:last-child td {
      border-bottom: none;
    }

    .product-image {
      width: 80px;
      height: 80px;
      
      ${devices.tablet} {
        width: 100px;
        height: 100px;
      }
      background: #E5E5E5;
      border-radius: 8px;
      margin: 0 auto;
    }

    .price {
      color: #8B5CF6;
      font-weight: 500;
    }
  }
`;

const GallerySection = styled.section`
  h2 {
    font-size: 20px;
    
    ${devices.tablet} {
      font-size: 24px;
    }
    color: #333;
    margin-bottom: 30px;

    ${devices.tablet} {
      margin-bottom: 40px;
    }
  }

  .gallery-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;

    ${devices.tablet} {
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }

    ${devices.laptop} {
      grid-template-columns: repeat(5, 1fr);
    }

    .gallery-item {
      aspect-ratio: 1;
      background: #E5E5E5;
      border-radius: 8px;
    }
  }
`;

const Scales: React.FC = () => {
  const bannerItems: BannerItem[] = [
    {
      imageUrl: '#',
      alt: 'Products Banner',
      overlay: true,
      darkOverlay: true,
      textPosition: 'center',
      content: {
        title: 'TAKE THE FIRST STEP TOWARDS1',
        description: 'A HEALTHIER YEAR',
        buttonText: 'Discover',
        buttonLink: '/scales'
      }
    },
    {
      imageUrl: '#',
      alt: 'Products Banner',
      overlay: true,
      darkOverlay: true,
      textPosition: 'center',
      content: {
        title: 'TAKE THE FIRST STEP TOWARDS2',
        description: 'A HEALTHIER YEAR',
        buttonText: 'Discover',
        buttonLink: '/scales'
      }
    }
  ];

  return (
    <PageWrapper>
      <ProductsWrapper>
        <Banner items={bannerItems} showArrows={true} />
        <MainContent>
          <HeroSection>
            <div className="text-content">
              <h1>Your health butler</h1>
              <p>The first body scale with wireless connectivity is here.<br />
                 Now you can track your progress and manage all your health data in one place.</p>
              <button>ABOUT US</button>
            </div>
            <div className="image-content" />
          </HeroSection>

          <ProductSection>
            <h2>BODY FAT SCALES</h2>
            <ProductGrid>
              {[1, 2, 3].map(index => (
                <ProductCard key={index}>
                  <div className="product-image" />
                  <div className="product-dots">
                    <span></span>
                    <span></span>
                    <span></span>
                  </div>
                  <h3>Professional Smart Scale Body Weight</h3>
                  <p>Professional body composition analysis, 13 core indicators</p>
                  <button>SHOP NOW</button>
                </ProductCard>
              ))}
            </ProductGrid>
          </ProductSection>

          <ProductSection>
            <h2>BODY WEIGHT SCALES</h2>
            <ProductGrid>
              {[1, 2].map(index => (
                <ProductCard key={index}>
                  <div className="product-image" />
                  <div className="product-dots">
                    <span></span>
                    <span></span>
                    <span></span>
                  </div>
                  <h3>Professional Smart Scale Body Weight</h3>
                  <p>Professional body composition analysis, 13 core indicators</p>
                  <button>SHOP NOW</button>
                </ProductCard>
              ))}
            </ProductGrid>
          </ProductSection>

          <ComparisonSection>
            <h2>Product Comparison</h2>
            <table className="comparison-table">
              <thead>
                <tr>
                  <th>Model</th>
                  <th>
                    <div className="product-image" />
                    Ovutek 1
                  </th>
                  <th>
                    <div className="product-image" />
                    Ovutek 2
                  </th>
                  <th>
                    <div className="product-image" />
                    Ovutek 3
                  </th>
                  <th>
                    <div className="product-image" />
                    Ovutek 4
                  </th>
                  <th>
                    <div className="product-image" />
                    Ovutek 5
                  </th>
                </tr>
              </thead>
              <tbody>
                <tr>
                  <td>Size</td>
                  <td>300×300×25mm</td>
                  <td>300×300×25mm</td>
                  <td>300×300×25mm</td>
                  <td>300×300×25mm</td>
                  <td>300×300×25mm</td>
                </tr>
                <tr>
                  <td>Weight</td>
                  <td>1.5kg</td>
                  <td>1.5kg</td>
                  <td>1.5kg</td>
                  <td>1.5kg</td>
                  <td>1.5kg</td>
                </tr>
                <tr>
                  <td>Display</td>
                  <td>LED</td>
                  <td>LED</td>
                  <td>LED</td>
                  <td>LED</td>
                  <td>LED</td>
                </tr>
                <tr>
                  <td>Connectivity</td>
                  <td>Bluetooth</td>
                  <td>Bluetooth</td>
                  <td>Bluetooth</td>
                  <td>Bluetooth</td>
                  <td>Bluetooth</td>
                </tr>
                <tr>
                  <td>Battery</td>
                  <td>4×AAA</td>
                  <td>4×AAA</td>
                  <td>4×AAA</td>
                  <td>4×AAA</td>
                  <td>4×AAA</td>
                </tr>
                <tr>
                  <td>Price</td>
                  <td className="price">$99.99</td>
                  <td className="price">$129.99</td>
                  <td className="price">$159.99</td>
                  <td className="price">$179.99</td>
                  <td className="price">$199.99</td>
                </tr>
              </tbody>
            </table>
          </ComparisonSection>

          <GallerySection>
            <h2>Advanced Technology Superior Health</h2>
            <div className="gallery-grid">
              {[1, 2, 3, 4, 5].map(index => (
                <div key={index} className="gallery-item" />
              ))}
            </div>
          </GallerySection>
        </MainContent>
      </ProductsWrapper>
    </PageWrapper>
  );
};

export default Scales; 